Item.method_code:
if (CCO.Permissions.UserHasRootIdentity())
{
  return this;
}

Innovator innovator = this.getInnovator();
string message = CCO.ErrorLookup.Lookup("cui_NotEnoughPermissions");
string itemSealedProp = this.getProperty("sealed");
if (string.Equals(itemSealedProp, "1", StringComparison.Ordinal))
{
	return innovator.newError(message);
}

string controlId = this.getID();
Item originControl = innovator.newItem("cui_Control", "get");
originControl.setID(controlId);
originControl.setAttribute("select", "sealed");
originControl = originControl.apply();
if (originControl.isError())
{
	return originControl;
}

string originControlSealedProp = originControl.getProperty("sealed");
if (string.Equals(originControlSealedProp, "1", StringComparison.Ordinal))
{
	return innovator.newError(message);
}

return this;
